import sys

def binary_search(a, target):
    l, r = 0, len(a) - 1
    while l <= r:
        mid = (l + r) // 2
        if a[mid] == target:
            return mid
        if a[mid] < target:
            l = mid + 1
        else:
            r = mid - 1
    return -1

def lower_bound(a, target):
    l, r = 0, len(a)
    while l < r:
        mid = (l + r) // 2
        if a[mid] < target:
            l = mid + 1
        else:
            r = mid
    return l

def count_pairs_sorted(a, target):
    a = sorted(a)
    l, r = 0, len(a) - 1
    cnt = 0
    while l < r:
        s = a[l] + a[r]
        if s == target:
            cnt += 1
            l += 1
            r -= 1
        elif s < target:
            l += 1
        else:
            r -= 1
    return cnt

def can_cut(trees, h, need):
    got = sum((t - h) for t in trees if t > h)
    return got >= need

def max_cut_height(trees, need):
    l, r = 0, max(trees) if trees else 0
    ans = 0
    while l <= r:
        mid = (l + r) // 2
        if can_cut(trees, mid, need):
            ans = mid
            l = mid + 1
        else:
            r = mid - 1
    return ans

def solve():
