        self.fact=[1]*(n+1)
        for i in range(1,n+1): self.fact[i]=self.fact[i-1]*i%MOD
        self.invFact=[1]*(n+1)
        self.invFact[n]=modpow(self.fact[n], MOD-2)
        for i in range(n,0,-1): self.invFact[i-1]=self.invFact[i]*i%MOD
    def C(self,n,r):
