## 3. 구현

### C++ - DSU, 크루스칼, 칸

```cpp
# include <bits/stdc++.h>
using namespace std;

// DSU
struct DSU {
    vector<int> p, sz;
    DSU(int n=0){init(n);}
    void init(int n){
        p.resize(n+1); sz.assign(n+1,1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x){
        if(p[x]==x) return x;
        return p[x]=find(p[x]); // path compression
    }
    bool unite(int a,int b){
        a=find(a); b=find(b);
        if(a==b) return false;
        if(sz[a]<sz[b]) swap(a,b);
        p[b]=a; sz[a]+=sz[b];
        return true;
    }
    bool same(int a,int b){return find(a)==find(b);}
};

// Kruskal MST: returns total weight, -1 if disconnected
long long kruskal(int n, vector<array<int,3>>& edges){
    sort(edges.begin(), edges.end(), [](auto &a, auto &b){return a[2]<b[2];});
    DSU dsu(n);
    long long total=0;
    int taken=0;
    for(auto &e: edges){
        int u=e[0], v=e[1], w=e[2];
        if(dsu.unite(u,v)){
            total+=w;
            if(++taken==n-1) break;
        }
    }
    if(taken!=n-1) return -1;
    return total;
}

// Topological sort Kahn: returns order, empty if cycle
vector<int> topoSort(int n, const vector<vector<int>>& adj){
    vector<int> indeg(n+1,0);
    for(int u=1;u<=n;u++) for(int v: adj[u]) indeg[v]++;
    queue<int> q;
    for(int i=1;i<=n;i++) if(indeg[i]==0) q.push(i);
    vector<int> order;
    while(!q.empty()){
        int u=q.front(); q.pop();
        order.push_back(u);
        for(int v: adj[u]){
            if(--indeg[v]==0) q.push(v);
        }
    }
    if((int)order.size()!=n) return {}; // cycle
    return order;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n,m; if(!(cin>>n>>m)) return 0;
    vector<array<int,3>> edges;
    vector<vector<int>> adj(n+1);
    for(int i=0;i<m;i++){
        int u,v,w; cin>>u>>v>>w;
        edges.push_back({u,v,w});
        adj[u].push_back(v); // for topo treat w as extra, but example uses directed
    }
    // For MST, use undirected edges; for topo, adjacency as built
    // Demo outputs:
    cout<<"MST "<<kruskal(n, edges)<<"\n";
    auto order=topoSort(n, adj);
    if(order.empty()) cout<<"CYCLE\n";
    else{ for(int x: order) cout<<x<<' '; cout<<"\n";}
    return 0;
}

```
### Python - 동일한 논리

```python
import sys
from collections import deque

class DSU:
    def __init__(self,n):
        self.p=list(range(n+1))
        self.sz=[1]*(n+1)
    def find(self,x):
        if self.p[x]!=x:
            self.p[x]=self.find(self.p[x])
        return self.p[x]
    def unite(self,a,b):
        a=self.find(a); b=self.find(b)
        if a==b:
            return False
        if self.sz[a]<self.sz[b]:
            a,b=b,a
        self.p[b]=a
        self.sz[a]+=self.sz[b]
        return True

def kruskal(n, edges):
    edges=sorted(edges, key=lambda e:e[2])
    dsu=DSU(n)
    total=0; taken=0
    for u,v,w in edges:
        if dsu.unite(u,v):
            total+=w; taken+=1
            if taken==n-1: break
    return -1 if taken!=n-1 else total

def topo_sort(n, adj):
    indeg=[0]*(n+1)
    for u in range(1,n+1):
        for v in adj[u]:
            indeg[v]+=1
    q=deque([i for i in range(1,n+1) if indeg[i]==0])
    order=[]
    while q:
        u=q.popleft()
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                q.append(v)
    if len(order)!=n:
        return None
    return order

def solve():
    data=sys.stdin.read().strip().split()
    if not data: return
    it=iter(data)
    n=int(next(it)); m=int(next(it))
    edges=[]; adj=[[] for _ in range(n+1)]
    for _ in range(m):
        try:
            u=int(next(it)); v=int(next(it)); w=int(next(it))
        except: break
        edges.append((u,v,w))
        adj[u].append(v)
    sys.stdout.write(f"MST {kruskal(n, edges)}\n")
    order=topo_sort(n, adj)
    if order is None:
        sys.stdout.write("CYCLE\n")
    else:
        sys.stdout.write(" ".join(map(str, order))+"\n")

if __name__=="__main__":
    solve()

```
