### C++ - Dinic O(E sqrt(V)? 실제로는 O(V² E) 최악이지만 빠릅니다.) + 이분의 경우 Hopcroft-Karp

```cpp
# include <bits/stdc++.h>
using namespace std;

struct Dinic{
    struct Edge{int to; long long cap; int rev;};
    int N;
    vector<vector<Edge>> G;
    vector<int> level, it;
    Dinic(int n=0){init(n);}
    void init(int n){ N=n; G.assign(n,{}); }
    void addEdge(int fr,int to,long long cap){
        Edge a{to,cap,(int)G[to].size()};
        Edge b{fr,0,(int)G[fr].size()};
        G[fr].push_back(a);
        G[to].push_back(b);
    }
    bool bfs(int s,int t){
        level.assign(N,-1);
        queue<int> q; level[s]=0; q.push(s);
        while(!q.empty()){
            int v=q.front(); q.pop();
            for(auto &e: G[v]) if(e.cap>0 && level[e.to]<0){
                level[e.to]=level[v]+1;
                q.push(e.to);
            }
        }
        return level[t]>=0;
    }
    long long dfs(int v,int t,long long f){
        if(v==t) return f;
        for(int &i=it[v]; i<(int)G[v].size(); ++i){
            Edge &e=G[v][i];
            if(e.cap>0 && level[v] < level[e.to]){
                long long d=dfs(e.to,t, min(f,e.cap));
                if(d>0){
                    e.cap-=d;
                    G[e.to][e.rev].cap+=d;
                    return d;
                }
            }
        }
        return 0;
    }
    long long maxflow(int s,int t){
        long long flow=0, INF=4e18;
        while(bfs(s,t)){
            it.assign(N,0);
            long long f;
            while((f=dfs(s,t,INF))>0) flow+=f;
        }
        return flow;
    }
};

// Hopcroft-Karp for bipartite matching O(E sqrt(V))
struct HopcroftKarp{
    int nLeft, nRight;
    vector<vector<int>> adj; // left 0..nLeft-1 → right indices 0..nRight-1
    vector<int> dist, pairU, pairV;
    HopcroftKarp(int L,int R):nLeft(L),nRight(R){
        adj.assign(nLeft,{});
        pairU.assign(nLeft,-1);
        pairV.assign(nRight,-1);
        dist.resize(nLeft);
    }
    void addEdge(int u,int v){ adj[u].push_back(v); }
    bool bfs(){
        queue<int> q;
        for(int u=0;u<nLeft;u++){
            if(pairU[u]==-1){dist[u]=0; q.push(u);}
            else dist[u]=-1;
        }
        bool found=false;
        while(!q.empty()){
            int u=q.front(); q.pop();
            for(int v: adj[u]){
                int pu=pairV[v];
                if(pu!=-1 && dist[pu]==-1){
                    dist[pu]=dist[u]+1;
                    q.push(pu);
                }
                if(pu==-1) found=true;
            }
        }
        return found;
    }
    bool dfs(int u){
        for(int v: adj[u]){
            int pu=pairV[v];
            if(pu==-1 || (dist[pu]==dist[u]+1 && dfs(pu))){
                pairU[u]=v; pairV[v]=u; return true;
            }
        }
        dist[u]=-1;
        return false;
    }
    int maxMatching(){
        int matching=0;
        while(bfs()){
            for(int u=0;u<nLeft;u++) if(pairU[u]==-1 && dfs(u)) matching++;
        }
        return matching;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n,m; if(!(cin>>n>>m)) return 0;
    HopcroftKarp hk(n,m-n); // dummy example
    Dinic dinic(n+2);
    // Example edges reading format depends on problem - not generalized
    return 0;
}

```
