## 보충: Python 구현과 복잡도 증명

### Python - Bitmask DP and Convex Hull Trick Sketch

```python
import sys

def bitmask_dp_count(a, target):
    n=len(a)
    cnt=0
    for mask in range(1<<n):
        s=sum(a[i] for i in range(n) if mask>>i &1)
        if s==target: cnt+=1
    return cnt

# CHT for dp[i]=min(dp[j]+ (i-j)*C ) naive O(n^2) -> O(n) with deque if slopes monotonic
def cht_dp(n, C=10):
    dp=[10**18]*(n+1)
    dp[0]=0
    from collections import deque
    # lines y = m*x + b ; m = -2*j? simplified demo
    dq=deque()
    dq.append((0,0)) # m,b
    def eval_line(line, x): return line[0]*x+line[1]
    def bad(l1,l2,l3): # if l2 unnecessary
        # (b3-b1)/(m1-m3) < (b2-b1)/(m1-m2) cross multiply
        return (l3[1]-l1[1])*(l1[0]-l2[0]) < (l2[1]-l1[1])*(l1[0]-l3[0])
    for i in range(1,n+1):
        x=i
        while len(dq)>=2 and eval_line(dq[0],x) >= eval_line(dq[1],x):
            dq.popleft()
        best=eval_line(dq[0],x)
        dp[i]=best + x*x + C
        new_line=(-2*i, dp[i]+i*i)
        while len(dq)>=2 and bad(dq[-2], dq[-1], new_line):
            dq.pop()
        dq.append(new_line)
    return dp[n]

def solve():
    print(bitmask_dp_count([1,2,3],3))
    print(cht_dp(10))
if __name__=="__main__":
    solve()

```
**시간/공간 보충:** 비트마스크 `O(n*2^n)` 시간 `O(1)` extra;CHT는 정렬된 기울기를 사용하여 `O(n^2)` DP를 `O(n)` 또는 `O(n log n)`으로 줄입니다. dp+deque의 경우 공백 `O(n)`입니다.
